// PopulateEventMetadata stores pending event metadata (W3C SCXML 5.10).
// Note: event name is set separately via setCurrentEvent(); metadata supplies
// only the name the event ARRIVED under, when that is not its value's own.
func (p *StatechartHostInvokerOptionalPolicy) PopulateEventMetadata(meta *sce.EventMetadata) {
	// NL→IR Item C1 Path A: lift the dequeued event's typed payload from the
	// type-erased carrier into the typed policy field the native guards read
	// (twin of the C11 pop loop's `sm->pending_payload = evt.payload`).
	p.pendingPayloadTag = StatechartHostInvokerOptionalPayloadTagNone
	switch v := meta.TypedPayload.(type) {
	case StatechartHostInvokerOptionalDoneInvokeLookupPayload:
		p.pendingPayloadTag = StatechartHostInvokerOptionalPayloadTagDoneInvokeLookup
		p.pendingDoneInvokeLookupPayload = v
	}

	p.pendingEventData = meta.Data
}

// LiftTypedPayload binds the dequeued event's typed `_event.data` view from
// the data it carries (NL→IR Item C1 Path A).
//
// The typed carrier PopulateEventMetadata reads is filled by one producer, the
// generated Raise<Event> inject seam. Every other producer — <send> with
// <param>, an invoke forwarding either way, autoforward, BasicHTTP, mesh —
// fills EventMetadata.Data, so the schema's fields are read out of that here.
// A refusal is returned for the engine to raise as error.execution, which is
// what W3C SCXML 3.13 gives for a guard that cannot be evaluated.
func (p *StatechartHostInvokerOptionalPolicy) LiftTypedPayload(event StatechartHostInvokerOptionalEvent, meta *sce.EventMetadata) error {
	// A typed carrier already bound the view, so the producer was the
	// inject seam and there is nothing to read out of `Data`.
	if p.pendingPayloadTag != StatechartHostInvokerOptionalPayloadTagNone {
		return nil
	}
	switch event {
	case StatechartHostInvokerOptionalEventDoneInvokeLookup:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload StatechartHostInvokerOptionalDoneInvokeLookupPayload
		if payload.rows, err = sce.PayloadUnsigned[uint8](fields, "rows"); err != nil {
			return err
		}
		if payload.at, err = optional.Lift(fields, "at", func() (int64, error) { return sce.PayloadSigned64(fields, "at") }); err != nil {
			return err
		}
		if payload.label, err = optional.Lift(fields, "label", func() (string, error) { return sce.PayloadString(fields, "label") }); err != nil {
			return err
		}
		if payload.hit, err = optional.Lift(fields, "hit", func() (bool, error) { return sce.PayloadBool(fields, "hit") }); err != nil {
			return err
		}
		p.pendingDoneInvokeLookupPayload = payload
		p.pendingPayloadTag = StatechartHostInvokerOptionalPayloadTagDoneInvokeLookup
	}
	return nil

}

